"""Minimal SMILES graph parser + WL canonical certificate (offline analysis only)."""
import re
from collections import defaultdict

AROM = {'b':'B','c':'C','n':'N','o':'O','p':'P','s':'S','se':'Se','as':'As'}
VAL = {'B':3,'C':4,'N':3,'O':2,'P':3,'S':2,'F':1,'Cl':1,'Br':1,'I':1}

def tokenize(s):
    i=0; n=len(s); out=[]
    while i<n:
        c=s[i]
        if c=='[':
            j=s.index(']',i); out.append(('atom',s[i+1:j])); i=j+1
        elif c in 'BCNOPSFI':
            m=re.match(r'Cl|Br|[BCNOPSFI]', s[i:]); out.append(('atom',m.group(0))); i+=len(m.group(0))
        elif c in 'bcnops':
            m=re.match(r'se|as|[bcnops]', s[i:]); out.append(('atom',m.group(0))); i+=len(m.group(0))
        elif c in '-=#:$/\\':
            out.append(('bond',c)); i+=1
        elif c=='(' : out.append(('(',c)); i+=1
        elif c==')' : out.append((')',c)); i+=1
        elif c=='.' : out.append(('dot',c)); i+=1
        elif c=='%': out.append(('ring',s[i+1:i+3])); i+=3
        elif c.isdigit(): out.append(('ring',c)); i+=1
        else: i+=1
    return out

def parse_atom(tok):
    m=re.match(r'^(\d+)?([A-Za-z][a-z]?)(@{1,2})?(H\d*)?([+-]\d*|[+-]{1,3})?$', tok)
    if not m: return {'el':tok,'arom':False,'chg':0,'h':None}
    iso,el,ch,h,chg=m.groups()
    arom = el[0].islower()
    el = AROM.get(el, el.capitalize() if arom else el)
    charge=0
    if chg:
        if chg[0] in '+-':
            d=chg[1:] if len(chg)>1 else ''
            n=int(d) if d.isdigit() else len(chg)
            charge = n if chg[0]=='+' else -n
    hcount = None
    if h: hcount = 1 if h=='H' else int(h[1:])
    return {'el':el,'arom':arom,'chg':charge,'h':hcount}

def parse(smiles):
    toks=tokenize(smiles); atoms=[]; bonds=[]; stack=[]; prev=None; pending=None; rings={}
    frags=[]; cur=[]
    for kind,val in toks:
        if kind=='atom':
            a=parse_atom(val); a['idx']=len(atoms); atoms.append(a); cur.append(a['idx'])
            if prev is not None:
                b = pending if pending else (1.5 if (atoms[prev]['arom'] and a['arom']) else 1)
                bonds.append((prev,a['idx'],b))
            pending=None; prev=a['idx']
        elif kind=='bond': pending={'=':2,'#':3,':':1.5,'-':1,'$':4,'/':1,'\\':1}[val]
        elif kind=='(': stack.append(prev)
        elif kind==')': prev=stack.pop()
        elif kind=='dot': prev=None; frags.append(cur); cur=[]
        elif kind=='ring':
            if val in rings:
                other,pb=rings.pop(val)
                b = pending if pending else (1.5 if (atoms[other]['arom'] and atoms[prev]['arom']) else 1)
                bonds.append((other,prev,b)); pending=None
            else: rings[val]=(prev,pending); pending=None
    frags.append(cur)
    return atoms,bonds,[f for f in frags if f]

def neighbors(atoms,bonds):
    nb=defaultdict(list)
    for a,b,o in bonds:
        nb[a].append((b,o)); nb[b].append((a,o))
    for a in nb: nb[a].sort()
    return nb

def wl(atoms,bonds,rounds=6):
    nb=neighbors(atoms,bonds)
    colors={a['idx']:(atoms[a['idx']]['el'],atoms[a['idx']]['arom'],atoms[a['idx']]['chg'],len(nb[a['idx']])) for a in atoms}
    for _ in range(rounds):
        sig={i:(colors[i],tuple(sorted((colors[j],o) for j,o in nb[i]))) for i in colors}
        order={}
        for i,s in sorted(sig.items(), key=lambda kv: (str(kv[1]),kv[0])): order[i]=order.get(i,len(order))
        # compress by sorted signature string
        uniq={}; colors={}
        for i,s in sig.items():
            key=str(s)
            if key not in uniq: uniq[key]=len(uniq)
            colors[i]=uniq[key]
    return colors

def cert(smiles):
    """Canonical certificate per connected component; None if WL not discrete."""
    atoms,bonds,frags=parse(smiles)
    nb=neighbors(atoms,bonds)
    subs=[(atoms,bonds,f) for f in frags]
    out=[]
    for atoms,_,frag in subs:
        idx=set(frag)
        sub=[a for a in atoms if a['idx'] in idx]
        sb=[b for b in bonds if b[0] in idx and b[1] in idx]
        col=wl(sub,sb)
        if len(set(col.values()))!=len(col): return None
        # discrete: certificate = sorted adjacency signature
        sig=[]
        for a in sub:
            i=a['idx']
            sig.append((col[i], atoms[i]['el'], tuple(sorted((col[j],o) for j,o in nb[i] if j in idx))))
        out.append(tuple(sorted(sig)))
    return tuple(sorted(out))

def components(smiles):
    return [c.strip() for c in smiles.strip().split('.') if c.strip()]

def same_set(pred, target):
    pc, tc = components(pred), components(target)
    if len(pc)!=len(tc): return False
    used=[False]*len(tc)
    for p in pc:
        cp=cert(p)
        if cp is None: return None
        hit=False
        for k,t in enumerate(tc):
            if used[k]: continue
            ct=cert(t)
            if ct is not None and ct==cp: used[k]=True; hit=True; break
        if not hit: return False
    return True
