from collections import Counter, defaultdict
def comps(s): return {p.strip().lower() for p in str(s).strip().split('.') if p.strip()}
def load(runs):
    per=defaultdict(list); gold={}
    for r in runs:
        for f in sorted(glob.glob(f'{r}/USPTO/conversations/[0-9]*/sample-*.json')):
            j=json.load(open(f)); ex=f.split('/')[-2]
            per[ex].append(comps(j['prediction'])); gold[ex]=comps(j['target'])
    return per,gold
def plurality(sets):
    c=Counter(frozenset(s) for s in sets); top=max(c.values())
    for s in sets:
        if c[frozenset(s)]==top: return s
    return sets[0]
def union(sets): return set().union(*sets)
def inter(sets): return set.intersection(*sets)
def item_thr(sets, thr):
    cnt=Counter()
    for s in sets:
        for x in s: cnt[x]+=1
    return {x for x,c in cnt.items() if c>=thr*len(sets)}
def report(name, runs):
