from smi2 import parse

DEFAULT_VAL={'B':3,'C':4,'N':3,'O':2,'P':3,'S':2,'F':1,'Cl':1,'Br':1,'I':1,'Si':4}
def formula(smiles):
    atoms,bonds,frags=parse(smiles)
    nb={}
    for a,b,o in bonds:
        nb.setdefault(a,[]).append(o); nb.setdefault(b,[]).append(o)
    cnt=Counter()
    for a in atoms:
        el=a['el']; cnt[el]+=1
        arom=a['arom']
        # aromatic bond order contribution: count 1.5 -> use round in ring
        orders=nb.get(a['idx'],[])
        bo=sum(orders)
        if arom:
            # aromatic atom: assume valence 3 (C) with one H if only 2 connections
            h = 1 if len(orders)==2 else (0 if len(orders)==3 else None)
        else:
            if a['h'] is not None: h=a['h']
            else:
                bo=sum(min(o,2) if o!=1.5 else 1 for o in orders)
                v=DEFAULT_VAL.get(el)
                if v is None: h=None
                else: h=max(0, v-int(round(bo)))
                if arom: h=0
        if h: cnt['H']+=h
    return tuple(sorted(cnt.items()))
